<?php
namespace App\Domain\Products;use App\Models\Product;final class ProductDependencyInspector {public function inspect(Product $p):array{$nav=$p->navigationItems()->where('is_active',true)->count();$home=$p->homepageItems()->where('is_active',true)->count();$relations=Product::whereHas('relatedProducts',fn($q)=>$q->whereKey($p))->where('status','!=','archived')->count();$children=$p->editions()->count()+$p->featureGroups()->count()+$p->benefits()->count()+$p->specifications()->count()+$p->galleryItems()->count()+$p->useCases()->count()+$p->integrations()->count();return ['navigation'=>$nav,'homepage'=>$home,'relations'=>$relations,'children'=>$children,'blocked'=>$nav+$home+$relations>0];}}